START TRANSACTION;

UPDATE `report_templates`
SET `sql_template` = 'WITH {{target_instances}},
matching_instances AS MATERIALIZED (
  SELECT target_instances.*
  FROM target_instances
  WHERE {{active_condition_predicates}}
)
SELECT
  instance_uuid AS "Instance UUID",
  instance_hrid AS "Instance HRID",
  title AS "Title",
  selected_locations AS "Selected Location(s)",
  CASE :locationBasis
    WHEN ''effective_item'' THEN ''Effective item''
    WHEN ''permanent_item'' THEN ''Permanent item''
    WHEN ''holdings_no_items'' THEN ''Holdings with no items (Smith)''
    WHEN ''no_holdings'' THEN ''No holdings (Smith)''
  END AS "Location Basis",
  CASE :combine
    WHEN ''all'' THEN ''All conditions''
    WHEN ''any'' THEN ''Any condition''
  END AS "Match",
  {{active_condition_columns}}
FROM matching_instances
ORDER BY "Title" NULLS LAST, "Instance HRID" NULLS LAST, "Instance UUID"
LIMIT 100001',
    `parameters` = '[{"name":"locationIds","type":"multiselect","label":"Locations","required":false,"default":"","placeholder":"Search locations","description":"Active FOLIO locations used to scope candidate bibliographic records.","max_selections":100,"groupSelect":true,"options_db":"folio","options_sql":"SELECT loc.id AS value, COALESCE(campus.name || '' — '', '''') || COALESCE(lib.name || '' — '', '''') || loc.name || COALESCE('' ['' || loc.code || '']'', '''') AS label FROM inventory.location__t loc LEFT JOIN inventory.loclibrary__t lib ON lib.id = loc.library_id LEFT JOIN inventory.loccampus__t campus ON campus.id = lib.campus_id WHERE COALESCE(loc.is_active, true) ORDER BY campus.name, lib.name, loc.name, loc.code"},{"name":"locationBasis","type":"select","label":"Location basis","required":true,"default":"effective_item","options_db":"folio","options_sql":"SELECT value, label FROM (VALUES (''effective_item'', ''Effective item''), (''permanent_item'', ''Permanent item''), (''holdings_no_items'', ''Holdings with no items (Smith)''), (''no_holdings'', ''Instances with no holdings (Smith)'')) AS basis(value, label)"},{"name":"combine","type":"select","label":"Combine conditions","required":true,"default":"all","options":[{"value":"all","label":"All conditions (AND)"},{"value":"any","label":"Any condition (OR)"}]},{"name":"c1_marcTag","type":"text","label":"Condition 1 MARC tag","required":true,"default":"","placeholder":"655","input_mode":"numeric","pattern":"[0-9]{3}","max_length":3},{"name":"c1_occurrenceCondition","type":"select","label":"Condition 1 occurrence condition","required":false,"default":"has","options":[{"value":"has","label":"Has matching occurrence"},{"value":"missing","label":"Missing matching occurrence"}]},{"name":"c1_firstIndicator","type":"select","label":"Condition 1 first indicator","required":false,"default":"any","options":[{"value":"any","label":"Any"},{"value":"blank","label":"Blank (#)"},{"value":"char:0","label":"0"},{"value":"char: